CREATE TABLE regulatory_source_editions(id uuid PRIMARY KEY,hash text NOT NULL,metadata jsonb NOT NULL,mime text NOT NULL CHECK(mime IN ('application/pdf','text/html')),retrieved_at timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),acquisition text NOT NULL CHECK(acquisition IN ('server-fetch','operator-upload')),error text,prepared_by text NOT NULL,permission_reference text NOT NULL,rights_reference text NOT NULL,fingerprint text NOT NULL);
CREATE INDEX regulatory_source_document ON regulatory_source_editions((metadata->>'authority'),(metadata->>'documentKey'),recorded_at DESC);
CREATE TABLE regulatory_source_reviews(seq bigserial PRIMARY KEY,request_id uuid NOT NULL UNIQUE,edition_id uuid NOT NULL REFERENCES regulatory_source_editions(id),fingerprint text NOT NULL,decision text NOT NULL CHECK(decision IN ('publish','withdraw','supersede')),reason text NOT NULL,reviewer text NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX regulatory_source_review_head ON regulatory_source_reviews(edition_id,seq DESC);
CREATE TRIGGER regulatory_source_editions_immutable BEFORE UPDATE OR DELETE ON regulatory_source_editions FOR EACH ROW EXECUTE FUNCTION protect_reviewed_event_history();
CREATE TRIGGER regulatory_source_reviews_immutable BEFORE UPDATE OR DELETE ON regulatory_source_reviews FOR EACH ROW EXECUTE FUNCTION protect_reviewed_event_history();
